<script setup lang="ts">
import { onBeforeUnmount,onMounted,ref } from 'vue'
import { operationsApi } from './api'
import { errorText } from '../models/api'
import '../models/models.css'
const health=ref<Awaited<ReturnType<typeof operationsApi.health>>|null>(null),metrics=ref<Awaited<ReturnType<typeof operationsApi.metrics>>|null>(null),healthError=ref(''),metricsError=ref(''),loading=ref(true),updated=ref('')
let controller:AbortController|undefined,timer:ReturnType<typeof setTimeout>|undefined,disposed=false
async function refresh(){controller?.abort();controller=new AbortController();const signal=controller.signal;const results=await Promise.allSettled([operationsApi.health(signal),operationsApi.metrics(signal)]);if(disposed||signal.aborted)return;const [h,m]=results;if(h.status==='fulfilled'){health.value=h.value;healthError.value=''}else{health.value=null;healthError.value=errorText(h.reason)}if(m.status==='fulfilled'){metrics.value=m.value;metricsError.value=''}else{metrics.value=null;metricsError.value=errorText(m.reason)}loading.value=false;updated.value=new Date().toLocaleTimeString();if(timer)clearTimeout(timer);if(!disposed&&metrics.value)timer=setTimeout(()=>{void refresh()},10000)}
function percent(value:unknown){return typeof value==='number'&&Number.isFinite(value)?`${value.toFixed(1)}%`:'不可用'}
function gpu(){const values=metrics.value?.system.gpu;return Array.isArray(values)&&values[0]?percent(values[0].utilization_percent):'不可用'}
onMounted(refresh);onBeforeUnmount(()=>{disposed=true;controller?.abort();if(timer)clearTimeout(timer)})
</script>
<template><section class="model-workspace"><div class="model-actions page-actions"><UiButton class="secondary-button" @click="refresh">刷新诊断</UiButton></div><p v-if="loading" class="model-muted" role="status">正在读取诊断信息…</p><p v-else class="model-muted">最近读取 {{updated}} · 正常时每 10 秒刷新</p><section class="model-panel"><header><h3>服务健康</h3><span>{{health?.status==='ok'?'健康检查通过':'健康状态不可用'}}</span></header><p v-if="healthError" class="operation-feedback is-error" role="status">{{healthError}} · 非成功健康检查不会标记正常</p><template v-if="health"><p>运行会话 {{health.streams}}</p><p>数据库：{{health.database.configured?`${health.database.backend||'数据库'} · ${health.database.status} · ${health.database.schema||'未提供schema'}`:'未配置数据库，开发内存回退'}}</p></template></section><section class="model-panel"><header><h3>服务器资源</h3></header><p v-if="metricsError" class="operation-feedback is-error" role="status">{{metricsError}}</p><dl class="model-readiness"><div><dt>CPU</dt><dd>{{percent(metrics?.system.cpu_percent)}}</dd></div><div><dt>内存</dt><dd>{{percent(metrics?.system.memory_percent)}}</dd></div><div><dt>磁盘</dt><dd>{{percent(metrics?.system.disk_percent)}}</dd></div><div><dt>GPU</dt><dd>{{gpu()}}</dd></div></dl><p class="model-muted">缺失值显示不可用，不能视为零负载。CPU 为服务进程采样，内存和磁盘以服务端指标定义为准。</p></section><section class="model-panel"><header><h3>平台运行汇总</h3></header><p class="model-muted">汇总全部项目的运行会话，不返回项目或视频流明细。查看明细须显式进入对应项目。</p><dl class="model-readiness"><div><dt>运行会话数</dt><dd>{{metrics?.streams.total??'不可用'}}</dd></div><div><dt>已接收帧</dt><dd>{{metrics?.streams.framesReceived??'不可用'}}</dd></div><div><dt>已处理帧</dt><dd>{{metrics?.streams.framesProcessed??'不可用'}}</dd></div><div><dt>丢弃帧</dt><dd>{{metrics?.streams.framesDropped??'不可用'}}</dd></div></dl></section></section></template>
